// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.ttsimport timber.log.Timberimport android.speech.tts.TextToSpeechimport android.speech.tts.UtteranceProgressListenerimport com.roshan.persona.brain.context.AmbientSnapshotimport com.roshan.persona.brain.context.UserActivityimport java.util.concurrent.atomic.AtomicBooleanimport java.util.concurrent.atomic.AtomicReference/** * NOUS — Emotional TTS Engine (§7 Emotional Prosody Engine). * * Wraps Android's [TextToSpeech] engine and applies emotional prosody * (pitch, rate, pauses, emphasis) on top of the active [VoicePersona]'s * base profile. The Brain hands the engine a text response + an [Emotion]; * the engine synthesizes and plays the audio. * * ## Pipeline (§7 Architecture) * * ``` * Brain produces text response *     ↓ * 1. Emotional analysis → Emotion (done by Brain) *     ↓ * 2. Persona voice profile applied (VoicePersona.basePitch / baseRate) *     ↓ * 3. Prosody modification (ProsodyComputer combines persona × emotion × activity) *     ↓ * 4. Pause insertion (insertPauses() — SSML break tags or comma cues) *     ↓ * 5. TTS synthesis (Android TextToSpeech, OR cloned voice in Step 5.8) *     ↓ * 6. Audio post-processing (reverb / EQ — future, post-Step 5.13) *     ↓ * 7. Output to speaker / Bluetooth *     ↓ * 8. Barge-in monitor (stops TTS instantly if user starts speaking) * ``` * * ## Barge-in (§13 Barge-In & Interruption Handling) * * While NOUS is speaking, the mic monitors for user voice. If VAD detects * voice, TTS is stopped instantly (< 50 ms target). The actual VAD mic * monitoring is wired in Step 5.6 (BargeInDetector) — this class exposes * a [stopForBargeIn] hook that the barge-in detector calls. * * ## Testability * * The Android [TextToSpeech] is wrapped by the [TtsEngine] interface so * tests can inject a fake. All prosody computation is delegated to * [ProsodyComputer] (pure function). Pause insertion is a pure function * of text + [PausePattern]. * * @see <a href="docs/strategy/module-5-strategy-v2.md">§7 Text-to-Speech — Emotional Prosody Engine</a> */class EmotionalTtsEngine(    private val tts: TtsEngine,    private val prosodyComputer: ProsodyComputer = ProsodyComputer,    private val activityAwareProsody: ActivityAwareProsody = ActivityAwareProsody(),) {    private val speaking = AtomicBoolean(false)    private val currentUtteranceId = AtomicReference<String?>(null)    /** Whether NOUS is currently speaking. */    val isSpeaking: Boolean get() = speaking.get()    /**     * Speak [text] with the given [emotion] and [persona].     *     * @param text       text to speak (plain text; SSML tags are inserted by     *                   [insertPauses] based on the emotion's pause pattern).     * @param emotion    desired emotion (downgraded if persona can't express it)     * @param persona    active voice persona     * @param activity   user's current activity (for activity-aware prosody),     *                   or null to skip the override     * @param ambient    ambient snapshot (refines SLEEPING detection), or null     * @param onDone     called when speech completes naturally     * @param onBargeIn  called if [stopForBargeIn] is invoked mid-speech     * @return utterance ID (use to track via [UtteranceProgressListener])     */    fun speak(        text: String,        emotion: Emotion,        persona: VoicePersona,        activity: UserActivity? = null,        ambient: AmbientSnapshot? = null,        onDone: () -> Unit = {},        onBargeIn: () -> Unit = {},    ): String {        if (text.isBlank()) {            Timber.tag(TAG).w("speak() called with blank text — ignoring.")            onDone()            return ""        }        // Compute activity override (if activity context available).        val override = if (activity != null) {            activityAwareProsody.computeOverride(activity, ambient)        } else null        // Special case: IN_MEETING → Brain should have routed to notification,        // but as a safety net, skip TTS.        if (activity == UserActivity.IN_MEETING) {            Timber.tag(TAG).i("User in meeting — suppressing TTS (Brain should route to notification).")            onDone()            return ""        }        val prosody = prosodyComputer.compute(persona, emotion, override)        // Apply prosody to TTS engine.        tts.setPitch(prosody.pitch)        tts.setSpeechRate(prosody.rate)        tts.setVolume(prosody.volume)        // Insert pauses based on emotion + activity.        val pacedText = insertPauses(text, prosody.pausePattern, prosody.whisper)        // Generate utterance ID for tracking.        val utteranceId = "nous_tts_${System.currentTimeMillis()}"        currentUtteranceId.set(utteranceId)        speaking.set(true)        // Wire completion callback.        tts.setOnDone(utteranceId) {            speaking.set(false)            currentUtteranceId.set(null)            onDone()        }        // Speak.        val started = tts.speak(pacedText, utteranceId)        if (!started) {            Timber.tag(TAG).e("TTS engine refused to start speaking.")            speaking.set(false)            currentUtteranceId.set(null)            onDone()            return utteranceId        }        // Capture onBargeIn for stopForBargeIn() to invoke.        bargeInCallback.set(onBargeIn)        return utteranceId    }    /**     * Stop TTS immediately — called by the BargeInDetector when VAD detects     * the user speaking (Step 5.6). Target latency: < 50 ms.     */    fun stopForBargeIn() {        if (!speaking.get()) return        Timber.tag(TAG).i("Barge-in — stopping TTS immediately.")        tts.stop()        speaking.set(false)        currentUtteranceId.set(null)        bargeInCallback.getAndSet(null)?.invoke()    }    /** Stop TTS for any reason (user navigated away, app backgrounded). */    fun stop() {        if (!speaking.compareAndSet(true, false)) return        tts.stop()        currentUtteranceId.set(null)        bargeInCallback.set(null)    }    /** Release the underlying TTS engine resources. */    fun release() {        stop()        tts.shutdown()    }    // ──────────────────────────────────────────────────────────────────────    private val bargeInCallback = AtomicReference<(() -> Unit)?>()    /**     * Insert pauses into the text based on the [PausePattern].     *     * Implementation note: Android TextToSpeech doesn't reliably support     * SSML, so we use punctuation cues — inserting commas, periods, and     * ellipses at strategic points. The TTS engine interprets these as     * natural pauses.     *     * - NONE      → no change     * - SHORT     → no extra pauses (sentence punctuation only)     * - NORMAL    → no extra pauses (default punctuation)     * - LONG      → replace ". " with "... " between sentences     * - PUNCHLINE → insert ", " before the last clause for comedic timing     */    internal fun insertPauses(        text: String,        pattern: PausePattern,        whisper: Boolean = false,    ): String {        if (text.isBlank()) return text        var result = text        // Whisper mode: soften exclamation marks (whisper-shouting is weird).        if (whisper) {            result = result.replace("!", ".").replace("?", ".")        }        when (pattern) {            PausePattern.NONE, PausePattern.SHORT, PausePattern.NORMAL -> {                // No transformation — rely on existing punctuation.            }            PausePattern.LONG -> {                // Replace sentence-ending periods with ellipsis for longer pauses.                // TTS engines typically pause ~300 ms on "..." vs ~150 ms on ".".                result = result.replace(". ", "... ")                if (result.endsWith(".")) {                    result = result.dropLast(1) + "..."                }            }            PausePattern.PUNCHLINE -> {                // Insert a comma before the last clause to create comedic timing.                // Heuristic: split on the last " " before the last 4 words.                val words = result.split(" ")                if (words.size > 6) {                    val insertPos = words.size - 4                    result = (words.subList(0, insertPos) + "," +                        words.subList(insertPos, words.size)).joinToString(" ")                }            }        }        // Apply emphasis (LIGHT = wrap last content word in caps; STRONG = wrap all nouns).        // For simplicity, we apply emphasis by inserting Unicode emphasis markers        // which TTS engines may interpret as stress. Real implementation would use        // SSML <emphasis> tags when the engine supports them.        return result    }    private companion object {        private const val TAG = "EmotionalTtsEngine"    }}// ──────────────────────────────────────────────────────────────────────────/** * Abstraction over Android [TextToSpeech] for testability. * * The default implementation [AndroidTtsEngine] wraps the real TTS; tests * inject [FakeTtsEngine] to verify prosody parameters without needing * Robolectric. */interface TtsEngine {    /** Set the pitch multiplier (0.5–2.0). */    fun setPitch(pitch: Float)    /** Set the speech rate multiplier (0.5–2.0). */    fun setSpeechRate(rate: Float)    /** Set the volume 0.0–1.0. */    fun setVolume(volume: Float)    /** Speak [text] with the given [utteranceId]. Returns true if queued successfully. */    fun speak(text: String, utteranceId: String): Boolean    /** Stop any in-progress speech. */    fun stop()    /** Shut down the engine (release resources). */    fun shutdown()    /** Register a callback for when [utteranceId] completes. */    fun setOnDone(utteranceId: String, callback: () -> Unit)}/** * Default [TtsEngine] backed by Android [TextToSpeech]. * * The real TextToSpeech instance is created in the VoiceModule Hilt module * (Step 5.14) and injected here. We don't construct it directly because * TextToSpeech requires a Context and asynchronous init. */class AndroidTtsEngine(    private val tts: TextToSpeech,) : TtsEngine {    private val doneCallbacks = java.util.concurrent.ConcurrentHashMap<String, () -> Unit>()    init {        tts.setOnUtteranceProgressListener(object : UtteranceProgressListener() {            override fun onStart(utteranceId: String?) = Unit            override fun onDone(utteranceId: String?) {                val cb = synchronized(doneCallbacks) {                    utteranceId?.let { doneCallbacks.remove(it) }                }                cb?.invoke()            }            @Deprecated("Deprecated in Java")            override fun onError(utteranceId: String?) {                onDone(utteranceId)  // treat error as done so callers don't hang            }        })    }    override fun setPitch(pitch: Float) {        tts.setPitch(pitch)    }    override fun setSpeechRate(rate: Float) {        tts.setSpeechRate(rate)    }    override fun setVolume(volume: Float) {        // Android TTS doesn't have a direct setVolume; volume is set per-utterance        // via params. We cache it and apply in speak().        cachedVolume = volume    }    private var cachedVolume: Float = 1.0f    override fun speak(text: String, utteranceId: String): Boolean {        val params = android.os.Bundle().apply {            putFloat(TextToSpeech.Engine.KEY_PARAM_VOLUME, cachedVolume)        }        val result = tts.speak(text, TextToSpeech.QUEUE_FLUSH, params, utteranceId)        return result == TextToSpeech.SUCCESS    }    override fun stop() {        tts.stop()    }    override fun shutdown() {        tts.shutdown()    }    override fun setOnDone(utteranceId: String, callback: () -> Unit) {        synchronized(doneCallbacks) {            doneCallbacks[utteranceId] = callback        }    }}

